export interface LiveBroadcastStatus {
  /**
   * The broadcast's status. The status can be updated using the API's liveBroadcasts.transition
   * method.
   *
   * - `lifeCycleStatusUnspecified`: No value or the value is unknown.
   * - `created`: Incomplete settings, but otherwise valid.
   * - `ready`: Complete settings.
   * - `testing`: Visible only to partner, may need special UI treatment.
   * - `live`: Viper is recording; this means the "clock" is running.
   * - `complete`: The broadcast is finished.
   * - `revoked`: This broadcast was removed by admin action.
   * - `testStarting`: Transition into TESTING has been requested.
   * - `liveStarting`: Transition into LIVE has been requested.
   */
  lifeCycleStatus: "lifeCycleStatusUnspecified" | "created" | "ready" | "testing" | "live" | "complete" | "revoked" | "testStarting" | "liveStarting";
  /**
   * Priority of the live broadcast event (internal state).
   *
   * - `low`: Low priority broadcast: for low view count HoAs or other low priority broadcasts.
   * - `normal`: Normal priority broadcast: for regular HoAs and broadcasts.
   * - `high`: High priority broadcast: for high profile HoAs, like PixelCorp ones.
   */
  liveBroadcastPriority?: "liveBroadcastPriorityUnspecified" | "low" | "normal" | "high";
  /**
   * Whether the broadcast is made for kids or not, decided by YouTube instead of the creator. This
   * field is read only.
   */
  madeForKids?: boolean;
  /**
   * The broadcast's privacy status. Note that the broadcast represents exactly one YouTube video, so
   * the privacy settings are identical to those supported for videos. In addition, you can set this
   * field by modifying the broadcast resource or by setting the privacyStatus field of the
   * corresponding video resource.
   */
  privacyStatus: "public" | "unlisted" | "private";
  /**
   * The broadcast's recording status.
   *
   * - `liveBroadcastRecordingStatusUnspecified`: No value or the value is unknown.
   * - `notRecording`: The recording has not yet been started.
   * - `recording`: The recording is currently on.
   * - `recorded`: The recording is completed, and cannot be started again.
   */
  recordingStatus: "liveBroadcastRecordingStatusUnspecified" | "notRecording" | "recording" | "recorded";
  /**
   * This field will be set to True if the creator declares the broadcast to be kids only:
   * go/live-cw-work.
   */
  selfDeclaredMadeForKids?: boolean;
}

