/** Basic details about a video category, such as its localized title. */
export interface VideoStatus {
  /** Indicates if the video contains altered or synthetic media. */
  containsSyntheticMedia?: boolean;
  /** This value indicates if the video can be embedded on another website. */
  embeddable: boolean;
  /**
   * This value explains why a video failed to upload. This property is only present if the
   * uploadStatus property indicates that the upload failed.
   *
   * - `conversion`: Unable to convert video content.
   * - `invalidFile`: Invalid file format.
   * - `emptyFile`: Empty file.
   * - `tooSmall`: File was too small.
   * - `codec`: Unsupported codec.
   * - `uploadAborted`: Upload wasn't finished.
   */
  failureReason?: "conversion" | "invalidFile" | "emptyFile" | "tooSmall" | "codec" | "uploadAborted";
  /**
   * The video's license.
   *
   * - `youtube`: Standard YouTube license.
   * - `creativeCommon`: Creative Commons license.
   */
  license: "youtube" | "creativeCommon";
  madeForKids: boolean;
  /** The video's privacy status. */
  privacyStatus: "public" | "unlisted" | "private";
  /**
   * This value indicates if the extended video statistics on the watch page can be viewed by everyone.
   * Note that the view count, likes, etc will still be visible if this is disabled.
   */
  publicStatsViewable: boolean;
  /**
   * The date and time when the video is scheduled to publish. It can be set only if the privacy status
   * of the video is private..
   *
   * ISO 8601 date and time.
   */
  publishAt?: string;
  /**
   * This value explains why YouTube rejected an uploaded video. This property is only present if the
   * uploadStatus property indicates that the upload was rejected.
   *
   * - `copyright`: Copyright infringement.
   * - `inappropriate`: Inappropriate video content.
   * - `duplicate`: Duplicate upload in the same channel.
   * - `termsOfUse`: Terms of use violation.
   * - `uploaderAccountSuspended`: Uploader account was suspended.
   * - `length`: Video duration was too long.
   * - `claim`: Blocked by content owner.
   * - `uploaderAccountClosed`: Uploader closed his/her account.
   * - `trademark`: Trademark infringement.
   * - `legal`: An unspecified legal reason.
   */
  rejectionReason?: "copyright" | "inappropriate" | "duplicate" | "termsOfUse" | "uploaderAccountSuspended" | "length" | "claim" | "uploaderAccountClosed" | "trademark" | "legal";
  selfDeclaredMadeForKids?: boolean;
  /**
   * The status of the uploaded video.
   *
   * - `uploaded`: Video has been uploaded but not processed yet.
   * - `processed`: Video has been successfully processed.
   * - `failed`: Processing has failed. See FailureReason.
   * - `rejected`: Video has been rejected. See RejectionReason.
   * - `deleted`: Video has been deleted.
   */
  uploadStatus: "uploaded" | "processed" | "failed" | "rejected" | "deleted";
}

/**
 * Specifies suggestions on how to improve video content, including encoding hints, tag suggestions,
 * and editor suggestions.
 */
export interface VideoSuggestions {
  /**
   * A list of video editing operations that might improve the video quality or playback experience of
   * the uploaded video.
   */
  editorSuggestions?: ("videoAutoLevels" | "videoStabilize" | "videoCrop" | "audioQuietAudioSwap")[];
  /**
   * A list of errors that will prevent YouTube from successfully processing the uploaded video video.
   * These errors indicate that, regardless of the video's current processing status, eventually, that
   * status will almost certainly be failed.
   */
  processingErrors?: ("audioFile" | "imageFile" | "projectFile" | "notAVideoFile" | "docFile" | "archiveFile" | "unsupportedSpatialAudioLayout")[];
  /** A list of suggestions that may improve YouTube's ability to process the video. */
  processingHints?: ("nonStreamableMov" | "sendBestQualityVideo" | "sphericalVideo" | "spatialAudio" | "vrVideo" | "hdrVideo")[];
  /**
   * A list of reasons why YouTube may have difficulty transcoding the uploaded video or that might
   * result in an erroneous transcoding. These warnings are generated before YouTube actually processes
   * the uploaded video file. In addition, they identify issues that are unlikely to cause the video
   * processing to fail but that might cause problems such as sync issues, video artifacts, or a
   * missing audio track.
   */
  processingWarnings?: ("unknownContainer" | "unknownVideoCodec" | "unknownAudioCodec" | "inconsistentResolution" | "hasEditlist" | "problematicVideoCodec" | "problematicAudioCodec" | "unsupportedVrStereoMode" | "unsupportedSphericalProjectionType" | "unsupportedHdrPixelFormat" | "unsupportedHdrColorMetadata" | "problematicHdrLookupTable")[];
  /**
   * A list of keyword tags that could be added to the video's metadata to increase the likelihood that
   * users will locate your video when searching or browsing on YouTube.
   */
  tagSuggestions?: VideoSuggestionsTagSuggestion[];
}

/** A single tag suggestion with its relevance information. */
export interface VideoSuggestionsTagSuggestion {
  /**
   * A set of video categories for which the tag is relevant. You can use this information to display
   * appropriate tag suggestions based on the video category that the video uploader associates with
   * the video. By default, tag suggestions are relevant for all categories if there are no restricts
   * defined for the keyword.
   */
  categoryRestricts?: string[];
  /** The keyword tag suggested for the video. */
  tag?: string;
}

/** Freebase topic information related to the video. */
export interface VideoTopicDetails {
  /**
   * Similar to topic_id, except that these topics are merely relevant to the video. These are topics
   * that may be mentioned in, or appear in the video. You can retrieve information about each topic
   * using Freebase Topic API.
   */
  relevantTopicIds?: string[];
  /** A list of Wikipedia URLs that provide a high-level description of the video's content. */
  topicCategories?: string[];
  /**
   * A list of Freebase topic IDs that are centrally associated with the video. These are topics that
   * are centrally featured in the video, and it can be said that the video is mainly about each of
   * these. You can retrieve information about each topic using the < a
   * href="http://wiki.freebase.com/wiki/Topic_API">Freebase Topic API.
   */
  topicIds?: string[];
}

/** Specifies who is allowed to train on the video. */
export interface VideoTrainability {
  /**
   * Identifies what kind of resource this is. Value: the fixed string "youtube#videoTrainability".
   */
  kind?: string;
  /** Etag of this resource. */
  etag?: string;
  /**
   * Specifies who is allowed to train on the video. Valid values are: - a single string "all" - a
   * single string "none" - a list of allowed parties.
   */
  permitted?: string[];
  /** The ID of the video. */
  videoId?: string;
}

/** Branding properties for the watch. All deprecated. */
export interface WatchSettings {
  /** The text color for the video watch page's branded area. */
  backgroundColor?: string;
  /** An ID that uniquely identifies a playlist that displays next to the video player. */
  featuredPlaylistId?: string;
  /** The background color for the video watch page's branded area. */
  textColor?: string;
}

